// blog.min.js – Minified blog logic
class BlogManager{constructor(config={}){this.posts=config.posts||[];this.filteredPosts=[...this.posts];this.container=document.getElementById("blogPosts");this.searchInput=document.getElementById("searchInput");this.tagFilters=document.querySelectorAll(".filter-tag");this.init()}init(){this.searchInput?.addEventListener("input",e=>this.handleSearch(e.target.value));this.tagFilters?.forEach(t=>t.addEventListener("click",()=>this.handleTagClick(t)));this.render()}handleSearch(term){const s=term.toLowerCase().trim();this.filteredPosts=this.posts.filter(p=>p.title.toLowerCase().includes(s)||p.excerpt.toLowerCase().includes(s));this.render()}handleTagClick(tag){const a=tag.getAttribute("data-tag");this.tagFilters.forEach(t=>t.classList.remove("active"));tag.classList.add("active");this.filteredPosts=a==="all"?[...this.posts]:this.posts.filter(p=>p.tags.includes(a));this.render()}render(){if(!this.container)return;this.container.innerHTML="";this.filteredPosts.forEach(p=>{const card=document.createElement("div");card.className="blog-card";card.innerHTML=`<a href="posts/${p.slug}.html"><div class="blog-card-image" style="background-image:url('${p.image}')"></div><div class="blog-card-content"><h3>${p.title}</h3><p>${p.excerpt}</p><div class="blog-card-meta"><span>📅 ${p.date}</span><span>⏱️ ${p.readingTime} Min.</span></div></div></a>`;this.container.appendChild(card)})}}window.BlogManager=BlogManager
